import sys
from functools import lru_cache
sys.setrecursionlimit(10000)
L, R, k = (int(x) for x in sys.stdin.read().split())

def count_upto(n):
    """How many x in [1, n] have digit sum divisible by k and no two equal adjacent digits."""
    if n <= 0:
        return 0
    digits = [int(c) for c in str(n)]

    @lru_cache(maxsize=None)
    def go(pos, mod, last, tight, started):
        if pos == len(digits):
            return 1 if started and mod == 0 else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            next_tight = tight and d == limit
            if not started and d == 0:
                total += go(pos + 1, 0, 10, next_tight, False)       # still in the leading zeros; 10 = "no digit yet"
            elif started and d == last:
                continue                                              # equal neighbours are forbidden
            else:
                total += go(pos + 1, (mod + d) % k, d, next_tight, True)
        return total

    return go(0, 0, 10, True, False)

print(count_upto(R) - count_upto(L - 1))

