import java.util.*;

public class Main {
    static int k;
    static int[] digits;
    static long[][][][][] memo;

    static long go(int pos, int mod, int last, int tight, int started) {
        if (pos == digits.length) return (started == 1 && mod == 0) ? 1 : 0;
        if (memo[pos][mod][last][tight][started] >= 0) return memo[pos][mod][last][tight][started];
        int limit = tight == 1 ? digits[pos] : 9;
        long total = 0;
        for (int d = 0; d <= limit; d++) {
            int nextTight = (tight == 1 && d == limit) ? 1 : 0;
            if (started == 0 && d == 0) total += go(pos + 1, 0, 10, nextTight, 0);
            else if (started == 1 && d == last) continue;
            else total += go(pos + 1, (mod + d) % k, d, nextTight, 1);
        }
        return memo[pos][mod][last][tight][started] = total;
    }

    static long countUpto(long n) {
        if (n <= 0) return 0;
        String s = Long.toString(n);
        digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) digits[i] = s.charAt(i) - '0';
        memo = new long[s.length() + 1][k][11][2][2];
        for (long[][][][] a : memo) for (long[][][] b : a) for (long[][] c : b) for (long[] d : c) Arrays.fill(d, -1);
        return go(0, 0, 10, 1, 0);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long L = in.nextLong(), R = in.nextLong();
        k = in.nextInt();
        System.out.println(countUpto(R) - countUpto(L - 1));
    }
}

