typedef long long ll;
int k;
vector<int> digits;
ll memo[20][100][11][2][2];

ll go(int pos, int mod, int last, int tight, int started) {
    if (pos == (int)digits.size()) return (started && mod == 0) ? 1 : 0;
    ll& res = memo[pos][mod][last][tight][started];
    if (res >= 0) return res;
    int limit = tight ? digits[pos] : 9;
    ll total = 0;
    for (int d = 0; d <= limit; d++) {
        int next_tight = tight && d == limit;
        if (!started && d == 0) total += go(pos + 1, 0, 10, next_tight, 0);
        else if (started && d == last) continue;
        else total += go(pos + 1, (mod + d) % k, d, next_tight, 1);
    }
    return res = total;
}

ll count_upto(ll n) {
    if (n <= 0) return 0;
    string s = to_string(n);
    digits.clear();
    for (char c : s) digits.push_back(c - '0');
    memset(memo, -1, sizeof(memo));
    return go(0, 0, 10, 1, 0);
}

